  `type_of_bridge` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `age_of_bridge` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `structural_form` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
