CREATE TABLE `inspection_component_rating` (
  `id` int NOT NULL AUTO_INCREMENT,
  `bridge_inspection_id` int NOT NULL,
  `rating_id` int NOT NULL,
  `component_type` varchar(256) COLLATE utf8mb4_general_ci NOT NULL,
