INSERT INTO `structural_rating` VALUES (1,9,'Excellent condition','No visible distress/ deterioration observed.'),(2,8,'Very good condition','<5 % of area effected by any of the following: Honeycombing, Delamination, Spalling, minor cracks, exposed reinforcement. Unevenness due to wear & tear, no pot holes on concrete surface. Drainage spouts are functional.'),(3,7,'Good Condition','5 to 10 % of area effected by any of the following: Honeycombing, Delamination, Spalling, minor cracks, exposed\r\nreinforcement. Unevenness due to wear & tear, no pot holes on concrete surface. Drainage spouts are functional.'),(4,6,'Satisfactory condition','10 to 15 % of area effected by any of the following: Honeycombing, Delamination, Spalling, minor/medium cracks,\r\nexposed reinforcement. Unevenness due to wear & tear, no potholes on concrete surface. Drainage spouts are functional.'),(5,5,'Fair condition','15 to 25 % of area effected by any of the following: Honeycombing, Delamination, Spalling, medium cracks, exposed reinforcement. Unevenness due to wear & tear no pot holes on concrete surface. Drainage spouts are functional.'),(6,4,'Poor condition','25 to 30 % of area effected by any some of the following: Honeycombing, Delamination, Spalling, medium cracks,\r\nexposed reinforcement. Unevenness due to wear & tear, potholes on concrete surface. Drainage spouts are\r\nnon-functional.'),(7,3,'Serious condition','30 to 40 % of area effected by any of the following: Honeycombing, Delamination, Spalling, medium /major cracks,\r\nexposed reinforcement. Unevenness due to wear & tear, pot holes on concrete surface. Drainage spouts are non-functional.'),(8,2,'Critical condition','40 to 50 % of area effected by any of the following: Honeycombing, Delamination, Spalling, major cracks, exposed\r\nreinforcement. Unevenness due to wear & tear, potholes on concrete surface. Drainage spouts are non-functional.'),(9,1,'Imminent failure','50 to 60 % of area effected by any of the following: Honeycombing, Delamination, Spalling, major cracks, exposed\r\nreinforcement. Unevenness due to wear & tear, pot holes on concrete surface. Drainage spouts are non-functional.'),(10,0,'Failed condition','>60% of area effected by some of the following: Honeycombing, Delamination, Spalling, major cracks, exposed\r\nreinforcement. Unevenness due to wear & tear, pot holes on concrete surface. Drainage spouts are non-functional.');
